\\u667a\\u80fd\\u4f53\\u67b6\\u6784\\u4e25\\u683c\\u5bf9\\u9f50\\u89c4\\u8303\\n\\u4e3a\\u4e86\\u6392\\u9664\\u201c\\u6a21\\u578b\\u5bb9\\u91cf\\u5dee\\u5f02\\u201d\\u6216\\u201c\\u7b97\\u529b\\u504f\\u5dee\\u201d\\u9020\\u6210\\u7684\\u5e72\\u6270\\uff0c\\u5236\\u5b9a\\u4ee5\\u4e0b\\u516c\\u5e73\\u63a7\\u5236\\u6807\\u51c6\\uff1a\\n1. **\\u53c2\\u6570\\u91cf\\u5747\\u7b49\\u5316\\uff08Capacity Parity\\uff09**\\uff1a\\n   - **Flat PPO**\\uff1a\\u91c7\\u7528\\u6807\\u51c6 CNN/MLP \\u9aa8\\u5e72\\u7f51\\u7edc\\uff08\\u53c2\\u6570\\u91cf $N_{\\\\text{total}} = 1.20 \\\\times 10^6$\\uff09\\uff0c\\u8f93\\u51fa\\u539f\\u59cb\\u52a8\\u4f5c\\u7a7a\\u95f4\\u6982\\u7387\\u3002\\n   - **Hierarchical Agent (Option-Critic / 2-Level HRL)**\\uff1a\\u5143\\u7b56\\u7565\\u7f51\\u7edc\\uff08Option Policy $\\\\pi_\\\\Omega$, \\u53c2\\u6570\\u91cf $0.35 \\\\times 10^6$\\uff09+ \\u7ec8\\u6b62\\u51fd\\u6570\\uff08Termination $\\\\beta_\\\\omega$, \\u53c2\\u6570\\u91cf $0.05 \\\\times 10^6$\\uff09+ 2\\u4e2a\\u4e13\\u7528\\u4f4e\\u5c42\\u7b56\\u7565\\u7f51\\u7edc\\uff08\\u53c2\\u6570\\u91cf\\u5404 $0.40 \\\\times 10^6$\\uff09\\uff0c\\u603b\\u53c2\\u6570\\u91cf\\u4e25\\u683c\\u9650\\u5236\\u5728 $N_{\\\\text{total}} = 1.20 \\\\times 10^6 \\\\pm 2\\\\%$ \\u4e4b\\u5185\\u3002\\n2. **\\u89c2\\u6d4b\\u4e0e\\u52a8\\u4f5c\\u63a5\\u53e3\\u5b8c\\u5168\\u7edf\\u4e00**\\uff1a\\n   - **\\u89c2\\u6d4b\\u7a7a\\u95f4 $\\\\mathcal{S}$**\\uff1a\\u5168\\u5c40\\u7f51\\u683c\\u5c40\\u90e8\\u89c6\\u573a\\u5f20\\u91cf $O_t \\\\in \\\\mathbb{R}^{C \\\\times H \\\\times W}$\\uff08\\u901a\\u9053\\u5305\\u542b\\u5730\\u5f62\\u3001\\u8d44\\u6e90\\u5b9e\\u4f53\\u3001\\u654c\\u5bf9\\u6d77\\u76d7\\u5b9e\\u4f53\\uff09+ \\u81ea\\u8eab\\u72b6\\u6001\\u5411\\u91cf $v_t = [HP_t / HP_{\\\\max}, S_t / S_{\\\\text{norm}}, \\\\text{Velocity}_t]$\\u3002\\n   - **\\u52a8\\u4f5c\\u7a7a\\u95f4 $\\\\mathcal{A}$**\\uff1a\\u79bb\\u6563\\u57fa\\u5143\\u52a8\\u4f5c\\u96c6\\u5408 $\\\\mathcal{A} = \\\\{\\\\text{\\u822a\\u884c}_N, \\\\text{\\u822a\\u884c}_S, \\\\text{\\u822a\\u884c}_E, \\\\text{\\u822a\\u884c}_W, \\\\text{\\u5f00\\u706b\\u653b\\u51fb}, \\\\text{\\u4e3e\\u76fe\\u9632\\u5fa1}, \\\\text{\\u52a0\\u901f\\u89c4\\u907f}, \\\\text{\\u8d44\\u6e90\\u91c7\\u96c6}\\\\}$\\u3002\\u5c42\\u7ea7\\u667a\\u80fd\\u4f53\\u7684\\u4f4e\\u5c42\\u7b56\\u7565\\u8f93\\u51fa\\u4e0e\\u975e\\u5c42\\u7ea7\\u667a\\u80fd\\u4f53\\u8f93\\u51fa\\u7684\\u52a8\\u4f5c\\u7a7a\\u95f4\\u5b8c\\u5168\\u4e00\\u81f4\\u3002\\n3. **\\u8bad\\u7ec3\\u6d41\\u7a0b\\u4e0e\\u6837\\u672c\\u9884\\u7b97\\u4e00\\u81f4\\u6027**\\uff1a\\n   - \\u4e24\\u79cd\\u67b6\\u6784\\u5747\\u5728\\u5305\\u542b\\u5e38\\u6001\\u4e0e\\u9636\\u6bb5\\u5165\\u4fb5\\u7684\\u6807\\u51c6\\u57fa\\u51c6\\u73af\\u5883\\u4e2d\\u8bad\\u7ec3 $1.0 \\\\times 10^7$ \\u4e2a\\u73af\\u5883\\u4ea4\\u4e92\\u6b65\\uff08Environment Steps\\uff09\\uff0c\\u4f18\\u5316\\u5668\\u7edf\\u4e00\\u91c7\\u7528 Adam\\uff08\\u521d\\u59cb\\u5b66\\u4e60\\u7387 $3 \\\\times 10^{-4}$\\uff0c\\u914d\\u5408\\u7ebf\\u6027\\u8870\\u51cf\\uff09\\u3002\\n\\n---\\n\\n## \\u4e09\\u3001 \\u6307\\u6807\\u4f53\\u7cfb\\u4e0e\\u56e0\\u679c\\u63a8\\u65ad\\u5206\\u6790\\u8ba1\\u5212\\n\\n### 3.1 \\u6838\\u5fc3\\u5ea6\\u91cf\\u6307\\u6807\\u5b9a\\u4e49\\n1. **\\u603b\\u5b58\\u6d3b\\u65f6\\u957f\\uff08Total Survival Duration, $T_{\\\\text{surv}}$\\uff09**\\uff1a\\n   $$T_{\\\\text{surv}} = \\\\min \\\\{ t \\\\mid HP_t \\\\le 0 \\\\lor t = T_{\\\\max} \\\\}$$\\n   \\u82e5\\u8fbe\\u5230\\u5355\\u5c40\\u6700\\u5927\\u6b65\\u6570 $T_{\\\\max} = 5000$ \\u4ecd\\u672a\\u6b7b\\u4ea1\\uff0c\\u6807\\u8bb0\\u4e3a\\u53f3\\u622a\\u65ad\\uff08Right-Censored, $\\\\delta = 0$\\uff09\\uff1b\\u6b7b\\u4ea1\\u6807\\u8bb0\\u4e3a\\u4e8b\\u4ef6\\u53d1\\u751f\\uff08$\\\\delta = 1$\\uff09\\u3002\\n2. **\\u89e6\\u53d1\\u540e\\u5b58\\u6d3b\\u65f6\\u957f\\uff08Post-Trigger Survival Duration, $\\\\Delta T_{\\\\text{post}}$\\uff09**\\uff1a\\n   \\u9488\\u5bf9\\u89e6\\u53d1\\u4e8b\\u4ef6\\u6210\\u529f\\u7684\\u8f68\\u8ff9\\uff0c\\u5b9a\\u4e49\\u4ece\\u673a\\u5236\\u6fc0\\u6d3b\\u65f6\\u523b $t_{\\\\text{trig}} = \\\\min \\\\{t \\\\mid S_t \\\\ge S_{\\\\text{threshold}}\\\\}$ \\u5230\\u6b7b\\u4ea1\\u7684\\u65f6\\u95f4\\u6b65\\u8de8\\u5ea6\\uff1a\\n   $$\\\\Delta T_{\\\\text{post}} = T_{\\\\text{surv}} - t_{\\\\text{trig}}$$\\n3. **\\u884c\\u4e3a\\u9002\\u5e94\\u65f6\\u5ef6\\uff08Behavioral Adaptation Latency, $\\\\tau_{\\\\text{adapt}}$\\uff09**\\uff1a\\n   \\u5b9a\\u4e49\\u4e3a\\u5165\\u4fb5\\u53d1\\u751f\\u540e\\uff0c\\u667a\\u80fd\\u4f53\\u52a8\\u4f5c\\u5206\\u5e03\\u4ece\\u201c\\u91c7\\u96c6\\u4e3b\\u5bfc\\u5206\\u5e03\\u201d\\u6536\\u655b\\u81f3\\u201c\\u7a33\\u5b9a\\u9632\\u5fa1/\\u9003\\u9038\\u5206\\u5e03\\u201d\\u6240\\u9700\\u7684\\u65f6\\u95f4\\u6b65\\u3002\\u901a\\u8fc7\\u6ed1\\u52a8\\u7a97\\u53e3\\u8ba1\\u7b97\\u52a8\\u4f5c\\u5206\\u5e03\\u4e0e\\u9632\\u5fa1\\u52a8\\u4f5c\\u96c6\\u7684 Jensen-Shannon \\u6563\\u5ea6 $D_{\\\\text{JS}}$ \\u7a33\\u5b9a\\u6240\\u9700\\u65f6\\u95f4\\u3002\\n4. **\\u9632\\u5fa1\\u6548\\u80fd\\u6bd4\\uff08Defense Efficiency, $\\\\eta_{\\\\text{def}}$\\uff09**\\uff1a\\n   $$\\\\eta_{\\\\text{def}} = \\\\frac{\\\\Delta T_{\\\\text{post}}}{\\\\sum_{t=t_{\\\\text{trig}}}^{T_{\\\\text{surv}}} \\\\text{DamageReceived}_t}$$\\n   \\u53cd\\u6620\\u5355\\u4f4d\\u627f\\u53d7\\u4f24\\u5bb3\\u4e0b\\u7684\\u5b58\\u6d3b\\u7ef4\\u6301\\u80fd\\u529b\\u3002\\n\\n### 3.2 \\u56e0\\u679c\\u63a8\\u65ad\\u4e0e\\u7edf\\u8ba1\\u5efa\\u6a21\\u65b9\\u6848\\n\\n#### (1) \\u751f\\u5b58\\u5206\\u6790\\u6a21\\u578b\\uff1aKaplan-Meier \\u4e0e Log-Rank \\u68c0\\u9a8c\\n- \\u5bf9\\u5404\\u7ec4\\u522b\\u7684\\u5b58\\u6d3b\\u51fd\\u6570 $S(t) = P(T_{\\\\text{surv}} > t)$ \\u8fdb\\u884c\\u975e\\u53c2\\u6570 Kaplan-Meier \\u4f30\\u8ba1\\uff1a\\n  $$\\\\hat{S}(t) = \\\\prod_{t_i \\\\le t} \\\\left( 1 - \\\\frac{d_i}{n_i} \\\\right)$$\\n  \\u5176\\u4e2d $d_i$ \\u4e3a\\u65f6\\u95f4\\u70b9 $t_i$ \\u7684\\u6b7b\\u4ea1\\u4e2a\\u4f53\\u6570\\uff0c$n_i$ \\u4e3a\\u5f53\\u65f6\\u5904\\u4e8e\\u98ce\\u9669\\u4e2d\\u7684\\u4e2a\\u4f53\\u6570\\u3002\\n- \\u91c7\\u7528\\u53cc\\u6837\\u672c\\u4e0e\\u591a\\u6837\\u672c **Log-Rank \\u68c0\\u9a8c**\\uff08\\u66fc\\u585e\\u5c14-\\u79d1\\u514b\\u65af\\u68c0\\u9a8c\\uff09\\uff0c\\u4e25\\u683c\\u5bf9\\u6bd4\\uff1a\\n  - G1 \\u5bf9\\u6bd4 G2\\uff08\\u5165\\u4fb5\\u6761\\u4ef6\\u4e0b\\u6241\\u5e73\\u4e0e\\u5c42\\u7ea7\\u7684\\u5b58\\u6d3b\\u5dee\\u5f02\\uff09\\uff1b\\n  - G1 \\u5bf9\\u6bd4 G3 \\u4ee5\\u53ca G2 \\u5bf9\\u6bd4 G4\\uff08\\u4e24\\u67b6\\u6784\\u5404\\u81ea\\u5bf9\\u673a\\u5236\\u89e6\\u53d1\\u7684\\u8106\\u5f31\\u6027\\u66f2\\u7ebf\\uff09\\u3002\\n\\n#### (2) \\u534a\\u53c2\\u6570\\u98ce\\u9669\\u56de\\u5f52\\uff1a\\u6269\\u5c55 Cox \\u6bd4\\u4f8b\\u98ce\\u9669\\u6a21\\u578b\\uff08\\u65f6\\u53d8\\u534f\\u53d8\\u91cf\\uff09\\n\\u4e3a\\u7cbe\\u786e\\u91cf\\u5316\\u673a\\u5236\\u89e6\\u53d1\\u77ac\\u95f4\\u7684\\u77ac\\u65f6\\u6b7b\\u4ea1\\u98ce\\u9669\\u53d8\\u5316\\u5e76\\u63a7\\u5236\\u5185\\u751f\\u6df7\\u6dc6\\u53d8\\u91cf\\uff0c\\u6784\\u5efa\\u542b\\u65f6\\u53d8\\u56e0\\u5b50\\u7684 Cox \\u56de\\u5f52\\u6a21\\u578b\\uff1a\\n$$\\\\lambda(t | \\\\mathbf{X}_t) = \\\\lambda_0(t) \\\\exp \\\\left( \\\\beta_1 \\\\text{IsHierarchical} + \\\\beta_2 \\\\text{TriggerActive}(t) + \\\\beta_3 [\\\\text{IsHierarchical} \\\\times \\\\text{TriggerActive}(t)] + \\\\boldsymbol{\\\\gamma}^\\\\top \\\\mathbf{Z}_t \\\\right)$$\\n- **\\u65f6\\u53d8\\u81ea\\u53d8\\u91cf**\\uff1a$\\\\text{TriggerActive}(t) = \\\\mathbb{I}(t \\\\ge t_{\\\\text{trig}})$\\uff0c\\u5728\\u672a\\u89e6\\u53d1\\u524d\\u4e3a 0\\uff0c\\u89e6\\u53d1\\u540e\\u8dc3\\u8fc1\\u4e3a 1\\u3002\\n- **\\u534f\\u53d8\\u91cf\\u5411\\u91cf $\\\\mathbf{Z}_t$**\\uff1a\\u5305\\u62ec\\u5230\\u8fbe\\u89e6\\u53d1\\u70b9\\u65f6\\u7684\\u77ac\\u65f6\\u751f\\u547d\\u503c $HP(t_{\\\\text{trig}})$\\u3001\\u7d2f\\u79ef\\u79ef\\u5206\\u901f\\u7387 $\\\\frac{dS}{dt}$\\u3001\\u5f53\\u524d\\u5c40\\u90e8\\u5730\\u56fe\\u6d77\\u76d7\\u5bc6\\u5ea6\\u3002\\n- **\\u68c0\\u9a8c\\u6807\\u51c6**\\uff1a\\n  - $\\\\beta_2$ \\u53cd\\u6620\\u5165\\u4fb5\\u89e6\\u53d1\\u5e26\\u6765\\u7684\\u77ac\\u65f6\\u98ce\\u9669\\u6bd4\\u4e0a\\u5347\\uff08\\u9884\\u671f $\\\\beta_2 > 0$\\uff09\\uff1b\\n  - \\u6838\\u5fc3\\u5173\\u6ce8\\u4ea4\\u4e92\\u7cfb\\u6570 $\\\\beta_3$\\u3002\\u82e5 $\\\\beta_3 < 0$\\uff08\\u5bf9\\u5e94\\u98ce\\u9669\\u6bd4 $\\\\exp(\\\\beta_3) < 1$\\uff09\\u4e14 $p < 0.01$\\uff0c\\u5219\\u5728\\u7edf\\u8ba1\\u5b66\\u4e0a\\u8bc1\\u5b9e\\uff1a**\\u5c42\\u7ea7\\u5316\\u67b6\\u6784\\u663e\\u8457\\u524a\\u5f31\\u4e86\\u6d77\\u76d7\\u5165\\u4fb5\\u673a\\u5236\\u5e26\\u6765\\u7684\\u6b7b\\u4ea1\\u98ce\\u9669**\\u3002\\n\\n#### (3) \\u53cc\\u91cd\\u5dee\\u5206\\uff08Difference-in-Differences, DiD\\uff09\\u65b9\\u5dee\\u68c0\\u9a8c\\n\\u9488\\u5bf9 $\\\\Delta T_{\\\\text{post}}$ \\u548c\\u6807\\u51c6\\u5316\\u5b58\\u6d3b\\u7387\\uff0c\\u6267\\u884c $2 \\\\times 2$ \\u53cc\\u56e0\\u7d20\\u65b9\\u5dee\\u5206\\u6790\\uff08Two-way ANOVA\\uff09\\u4e0e DiD \\u56de\\u5f52\\uff1a\\n$$Y_{ij} = \\\\beta_0 + \\\\beta_1 \\\\text{Architecture}_i + \\\\beta_2 \\\\text{Mechanic}_j + \\\\beta_3 (\\\\text{Architecture}_i \\\\times \\\\text{Mechanic}_j) + \\\\epsilon_{ij}$$\\n\\u8ba1\\u7b97\\u4ea4\\u4e92\\u9879\\u6548\\u5e94\\u91cf Partial $\\\\eta^2$\\uff0c\\u9a8c\\u8bc1\\u5c42\\u7ea7\\u5316\\u6548\\u5e94\\u5728\\u73af\\u5883\\u538b\\u529b\\u4e0b\\u662f\\u5426\\u5177\\u6709\\u7a33\\u5065\\u7edf\\u8ba1\\u663e\\u8457\\u6027\\u3002\\n\\n---\\n\\n## \\u56db\\u3001 \\u53ef\\u884c\\u6027\\u4e0e\\u5b9e\\u65bd\\u7ec6\\u8282\\n\\n### 4.1 \\u6837\\u672c\\u91cf\\u4f30\\u7b97\\u4e0e\\u529f\\u6548\\u5206\\u6790\\uff08Power Analysis\\uff09\\n- \\u57fa\\u4e8e Monte Carlo \\u6a21\\u62df\\u5b9e\\u9a8c\\u7684\\u5148\\u9a8c\\u7edf\\u8ba1\\u6807\\u51c6\\uff1a\\u8bbe\\u5b9a\\u663e\\u8457\\u6027\\u6c34\\u5e73 $\\\\alpha = 0.05$\\uff0c\\u68c0\\u9a8c\\u529f\\u6548 $1 - \\\\beta = 0.90$\\uff0c\\u9884\\u8bbe\\u4e2d\\u7b49\\u6548\\u5e94\\u91cf Cohen's $f = 0.25$\\uff08\\u53cc\\u56e0\\u7d20 ANOVA \\u4ea4\\u4e92\\u9879